#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int exists(const char*p){FILE*f=fopen(p,"rb");if(!f)return 0;fclose(f);return 1;}
static int starts(const char*s,const char*p){return strncmp(s,p,strlen(p))==0;}
static const char*category(const char*m,const char*operands){
 if(starts(m,"call")||!strcmp(m,"bl")||!strcmp(m,"blr"))return "call";
 if(starts(m,"b.")||!strcmp(m,"b")||starts(m,"j")||starts(m,"cb")||starts(m,"tb")||starts(m,"bne")||starts(m,"beq")||starts(m,"bgt")||starts(m,"blt")||starts(m,"bge")||starts(m,"ble")||starts(m,"bhi")||starts(m,"bls"))return "branch";
 if(starts(m,"ldr")||starts(m,"ldp")||starts(m,"ldur")||starts(m,"str")||starts(m,"stp")||starts(m,"stur")||starts(m,"push")||starts(m,"pop"))return "load/store";
 if((starts(m,"mov")||starts(m,"lea"))&&(strchr(operands,'(')||strchr(operands,'[')))return "possible load/store";
 if(starts(m,"add")||starts(m,"sub")||starts(m,"mul")||starts(m,"div")||starts(m,"fma")||starts(m,"fmul")||starts(m,"fadd")||starts(m,"fsu")||starts(m,"cmp")||starts(m,"and")||starts(m,"orr")||starts(m,"xor")||starts(m,"lsl")||starts(m,"lsr"))return "arithmetic/compare";
 return "other instruction";
}
int main(int argc,char**argv){if(argc!=3){fprintf(stderr,"Usage: %s INPUT.s OUTPUT.md\n",argv[0]);return 2;}if(exists(argv[2])){fprintf(stderr,"refusing to overwrite annotation: %s\n",argv[2]);return 2;}FILE*in=fopen(argv[1],"rb");if(!in){perror(argv[1]);return 2;}FILE*out=fopen(argv[2],"wb");if(!out){perror(argv[2]);fclose(in);return 2;}fprintf(out,"# Compiler assembly annotations\n\n> Heuristic classification generated from the supplied assembly text. This is assistance for manual review, not a verified disassembly or human-reviewed explanation.\n\nSource listing: `%s`\n\n| Line | Symbol/label or instruction | Category | References | Review |\n|---:|---|---|---|---|\n",argv[1]);char line[4096];unsigned long number=0;while(fgets(line,sizeof line,in)){number++;size_t n=strlen(line);if(n==sizeof line-1&&line[n-1]!='\n'&&!feof(in)){fputs("assembly input line exceeds 4095 bytes\n",stderr);fclose(in);fclose(out);return 3;}if(n&&line[n-1]=='\n')line[--n]=0;if(n&&line[n-1]=='\r')line[--n]=0;char*t=line;while(isspace((unsigned char)*t))t++;if(!*t||*t=='#'||*t==';')continue;char*comment=strchr(t,'#');if(comment)*comment=0;char*end=t+strlen(t);while(end>t&&isspace((unsigned char)end[-1]))*--end=0;if(!*t)continue;char*colon=strchr(t,':');if(colon&&colon[1]==0){*colon=0;fprintf(out,"| %lu | `%s` | %s | - | verify symbol type and loop role |\n",number,t,starts(t,".L")?"local label":"symbol label; inspect function metadata");continue;}if(*t=='.')continue;char*m=t;char*split=m;while(*split&&!isspace((unsigned char)*split))split++;char save=*split;*split=0;char*operands=save?split+1:split;while(isspace((unsigned char)*operands))operands++;const char*cat=category(m,operands);const char*ref="-";if(strstr(operands,"now_ns")||strstr(operands,"clock_gettime")||strstr(operands,"QueryPerformanceCounter"))ref="timing reference present";else if(strstr(operands,"replay")||strstr(m,"replay"))ref="replay reference present";fprintf(out,"| %lu | `%s %s` | %s | %s | uncertain; verify source mapping |\n",number,m,operands,cat,ref);}
 fprintf(out,"\n## Manual review checklist\n\n- Find the actual replay main loop and the SMA update/crossover path in this exact listing.\n- Confirm load/store, arithmetic, branch, and call categories against the target ISA manual.\n- Trace data dependencies and loop bounds back to `src/replay_engine.c`; labels alone do not prove loop identity.\n- Verify whether timing calls are present in the listing; do not infer timing overhead from the source only.\n- Record architecture/compiler/flags from the adjacent manifest and review the original `.s` beside this annotation.\n");
 if(ferror(in)||ferror(out)){perror("assembly annotation I/O");fclose(in);fclose(out);return 3;}fclose(in);if(fclose(out)){perror(argv[2]);return 3;}printf("heuristic annotations written: %s\n",argv[2]);return 0;}
